from pathlib import Path
import json,shutil
ROOT=Path(__file__).resolve().parents[1]
r=ROOT
catalog=json.loads((r/'demo/catalog.json').read_text())['products'];settings=json.loads((r/'demo/settings.json').read_text())
html=(r/'static/index.html').read_text();html=html.replace('<button id="adminOpen" data-t="manage"></button>','<button id="adminOpen" data-t="manage" hidden></button>')
css=(r/'static/style.css').read_text();js=(r/'static/app.js').read_text()
# Pilot checkout persists real records, while the reference catalogue is clearly labelled.
js=js.replace("if(shopSettings.demo)for", "if(shopSettings.demo||shopSettings.pilot)for")
js=js.replace("banner.hidden=!shopSettings.demo;banner.textContent=shopSettings.demo?t('demoBanner'):'';","banner.hidden=true;banner.textContent='';")
js=js.replace("if(!shopSettings.demo){$('#paymentMethod').closest('label').hidden=true;$('#bankLinks').hidden=true}","if(!shopSettings.demo&&!shopSettings.pilot){$('#paymentMethod').closest('label').hidden=true;$('#bankLinks').hidden=true}")
js=js.replace("if(!o.demo)localStorage.setItem", "if(!o.demo)localStorage.setItem")
# Show a direct tracking action after a saved order.
js=js.replace("cart=[];save();await draw()", "cart=[];save();await draw();if(!o.demo){$('#drawer').close();document.querySelector('#tracking').scrollIntoView();$('#trackOrder').click()}")
for lang,old,new in [('ru','Оплата наличными или ручным переводом. В демо заказ не отправляется.','Оплата наличными или ручным переводом после согласования с оператором.'),('ka','ნაღდი ან ხელით გადარიცხვა. დემო შეკვეთა არ იგზავნება.','ნაღდი ან ხელით გადარიცხვა ოპერატორთან შეთანხმების შემდეგ.'),('hy','Կանխիկ կամ ձեռքով փոխանցում։ Դեմո պատվերը չի ուղարկվում։','Կանխիկ կամ ձեռքով փոխանցում՝ օպերատորի հետ համաձայնեցնելուց հետո։'),('en','Cash or a manual bank transfer. Demo orders are not sent.','Cash or manual transfer after confirmation by the operator.')]:js=js.replace(old,new)
api=(r/'worker/merchandising.mjs').read_text().replace('export const','const').replace('export function','function')+'\n'+(r/'worker/feast.mjs').read_text().replace('export const','const').replace('export function','function')+'\n'+(r/'worker/api.mjs').read_text().replace("import {rankCatalog,recommendProducts} from './merchandising.mjs';\n",'').replace("import {buildFeast} from './feast.mjs';\n",'').replace('export class','class').replace('export function','function').replace('export async function','async function')
assets={'/':html,'/style.css':css,'/app.js':js}
code='const CATALOG='+json.dumps(catalog,ensure_ascii=False)+';\nconst SETTINGS='+json.dumps(settings,ensure_ascii=False)+';\nconst ASSETS='+json.dumps(assets,ensure_ascii=False)+';\n'+api+'''\nexport default {async fetch(request,env,ctx){const path=new URL(request.url).pathname;if(path.startsWith('/api/'))return api(request,env,ctx,CATALOG,SETTINGS);if(/^\\/media\\/[a-f0-9]+\\.mp4$/.test(path)){const headers=new Headers();if(request.headers.has('Range'))headers.set('Range',request.headers.get('Range'));const video=await fetch('https://raw.githubusercontent.com/xugushik-source/Shashlicniy_ray/main/static'+path,{method:request.method==='HEAD'?'HEAD':'GET',headers});if(!video.ok)return new Response('Video unavailable',{status:404});const result=new Headers(video.headers);result.set('Content-Type','video/mp4');result.set('Cache-Control','public, max-age=86400');result.set('X-Content-Type-Options','nosniff');return new Response(video.body,{status:video.status,headers:result})}if(/^\\/media\\/[a-f0-9]+\\.(jpg|png|webp|jpeg)$/.test(path))return Response.redirect('https://raw.githubusercontent.com/xugushik-source/Shashlicniy_ray/main/static'+path,302);if(ASSETS[path]!==undefined)return new Response(ASSETS[path],{headers:{'Content-Type':path.endsWith('.js')?'text/javascript; charset=utf-8':path.endsWith('.css')?'text/css':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff','Cache-Control':'no-store','Content-Security-Policy':"default-src 'self'; img-src 'self' https:; style-src 'self'; script-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'"}});return new Response('Not found',{status:404})}};\n'''
out=r/'dist';shutil.rmtree(out,ignore_errors=True);(out/'server').mkdir(parents=True);(out/'server/index.js').write_text(code);shutil.copytree(r/'drizzle',out/'drizzle',dirs_exist_ok=True);(out/'.openai').mkdir();shutil.copy2(r/'.openai/hosting.json',out/'.openai/hosting.json');print('Worker built',len(code.encode()),'bytes')
